/**
 * @fileoverview A CommonJS package two CommonJS api files require inside a function, after they loaded. Loaded once per process, as Node loads a package's file; it keeps a count of its own.
 * @module count-later
 */
let count = 0;

/**
 * Count one up.
 * @returns {number} The count so far.
 */
function bump() {
	return ++count;
}

/**
 * Read the vault through the api object it is given: the access is this package's own code.
 * @param {object} api - The api to read through (`self`).
 * @returns {string} What the vault holds.
 */
function read(api) {
	return api.vault.get();
}

module.exports = { bump, read };
